import * as React from "react";
import { faIR, getDateLib } from "@daypicker/persian";

import { Calendar } from "@/registry/erbium/ui/calendar";

// The Jalali date library drives months, weeks, and numerals; Calendar keeps
// its styling and RTL layout.
const persianDateLib = getDateLib({ locale: faIR, numerals: "arabext" });

const CalendarPersian = () => {
  const [date, setDate] = React.useState<Date | undefined>(() => new Date());

  return (
    <Calendar
      mode="single"
      selected={date}
      onSelect={setDate}
      dateLib={persianDateLib}
      locale={faIR}
      numerals="arabext"
      dir="rtl"
      formatters={{
        formatWeekdayName: (weekday, _options, dateLib) =>
          (dateLib ?? persianDateLib).format(weekday, "ccccc"),
      }}
    />
  );
};

export default CalendarPersian;

import * as React from "react";

import { Button } from "@/registry/erbium/ui/button";
import { Calendar } from "@/registry/erbium/ui/calendar";
import { Card, CardContent, CardFooter } from "@/registry/erbium/ui/card";
import { addDays } from "@/registry/erbium/lib/date";

export const CalendarWithPresets = () => {
  const [date, setDate] = React.useState<Date | undefined>(
    () => new Date(new Date().getFullYear(), 1, 12),
  );

  const [currentMonth, setCurrentMonth] = React.useState<Date>(
    () => new Date(new Date().getFullYear(), new Date().getMonth(), 1),
  );

  return (
    <Card className="mx-auto w-fit max-w-[300px]" size="sm">
      <CardContent>
        <Calendar
          mode="single"
          selected={date}
          onSelect={setDate}
          month={currentMonth}
          onMonthChange={setCurrentMonth}
          fixedWeeks
          className="p-0 [--cell-size:--spacing(9.5)]"
        />
      </CardContent>
      <CardFooter className="flex flex-wrap gap-related">
        {[
          { label: "Today", value: 0 },
          { label: "Tomorrow", value: 1 },
          { label: "In 3 days", value: 3 },
          { label: "In a week", value: 7 },
          { label: "In 2 weeks", value: 14 },
        ].map((preset) => (
          <Button
            key={preset.value}
            variant="outline"
            size="sm"
            className="flex-1"
            onClick={() => {
              const newDate = addDays(new Date(), preset.value);
              setDate(newDate);
              setCurrentMonth(new Date(newDate.getFullYear(), newDate.getMonth(), 1));
            }}
          >
            {preset.label}
          </Button>
        ))}
      </CardFooter>
    </Card>
  );
};

